command:
// The whole hazard turn lives in the module: 1d3 for the anchor, the destroyed short circuit
// (never rerolled), a random painted sector, the matching template, and one whispered card.
const api = game.modules.get('tatzleford-tempest')?.api;
if (!api?.hazardTurn) {
  ui.notifications.error('Enable the Queen\'s Tempest module to roll the hazard routine.');
} else {
  await api.hazardTurn();
}
